import { Router } from 'express'
import { runSavedSearch } from '../services/search-runner'
import {
  createSearch,
  deleteSearch,
  getAllSearches,
  updateSearch,
} from '../store/searches'

const router = Router()

router.get('/', async (_req, res) => {
  try {
    const searches = await getAllSearches()
    res.json(searches)
  } catch {
    res.status(500).json({ error: 'Failed to load searches' })
  }
})

router.post('/', async (req, res) => {
  const { name, query, maxPrice, location, radius, resultsPerSearch } = req.body

  if (!name || typeof name !== 'string' || !name.trim()) {
    res.status(400).json({ error: 'Name is required' })
    return
  }

  if (!query || typeof query !== 'string' || !query.trim()) {
    res.status(400).json({ error: 'Query is required' })
    return
  }

  if (!location || typeof location !== 'string' || !location.trim()) {
    res.status(400).json({ error: 'Location is required' })
    return
  }

  if (radius === undefined || typeof radius !== 'number' || radius <= 0) {
    res.status(400).json({ error: 'Radius must be a positive number' })
    return
  }

  if (
    maxPrice !== undefined &&
    maxPrice !== null &&
    (typeof maxPrice !== 'number' || maxPrice <= 0)
  ) {
    res.status(400).json({ error: 'Max price must be a positive number' })
    return
  }

  if (
    resultsPerSearch !== undefined &&
    (typeof resultsPerSearch !== 'number' ||
      ![5, 10, 20, 50].includes(resultsPerSearch))
  ) {
    res.status(400).json({ error: 'Results per search must be 5, 10, 20, or 50' })
    return
  }

  try {
    const search = await createSearch({
      name: name.trim(),
      query: query.trim(),
      maxPrice: maxPrice ?? null,
      location: location.trim(),
      radius,
      resultsPerSearch: resultsPerSearch ?? 10,
    })
    res.status(201).json(search)
  } catch {
    res.status(500).json({ error: 'Failed to create search' })
  }
})

router.patch('/:id', async (req, res) => {
  const { name, query, maxPrice, location, radius, resultsPerSearch } = req.body

  if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
    res.status(400).json({ error: 'Name is required' })
    return
  }

  if (query !== undefined && (typeof query !== 'string' || !query.trim())) {
    res.status(400).json({ error: 'Query is required' })
    return
  }

  if (location !== undefined && (typeof location !== 'string' || !location.trim())) {
    res.status(400).json({ error: 'Location is required' })
    return
  }

  if (radius !== undefined && (typeof radius !== 'number' || radius <= 0)) {
    res.status(400).json({ error: 'Radius must be a positive number' })
    return
  }

  if (
    maxPrice !== undefined &&
    maxPrice !== null &&
    (typeof maxPrice !== 'number' || maxPrice <= 0)
  ) {
    res.status(400).json({ error: 'Max price must be a positive number' })
    return
  }

  if (
    resultsPerSearch !== undefined &&
    (typeof resultsPerSearch !== 'number' ||
      ![5, 10, 20, 50].includes(resultsPerSearch))
  ) {
    res.status(400).json({ error: 'Results per search must be 5, 10, 20, or 50' })
    return
  }

  try {
    const search = await updateSearch(req.params.id, {
      ...(name !== undefined && { name: name.trim() }),
      ...(query !== undefined && { query: query.trim() }),
      ...(location !== undefined && { location: location.trim() }),
      ...(radius !== undefined && { radius }),
      ...(maxPrice !== undefined && { maxPrice }),
      ...(resultsPerSearch !== undefined && { resultsPerSearch }),
    })

    if (!search) {
      res.status(404).json({ error: 'Search not found' })
      return
    }

    res.json(search)
  } catch {
    res.status(500).json({ error: 'Failed to update search' })
  }
})

router.post('/:id/run', async (req, res) => {
  try {
    const result = await runSavedSearch(req.params.id)

    if (!result) {
      res.status(404).json({ error: 'Search not found' })
      return
    }

    res.json(result)
  } catch (error) {
    console.error('Failed to run search:', error)

    if (error instanceof Error && error.cause) {
      console.error('Caused by:', error.cause)
    }

    res.status(500).json({ error: 'Failed to run search' })
  }
})

router.delete('/:id', async (req, res) => {
  try {
    const deleted = await deleteSearch(req.params.id)

    if (!deleted) {
      res.status(404).json({ error: 'Search not found' })
      return
    }

    res.status(204).send()
  } catch {
    res.status(500).json({ error: 'Failed to delete search' })
  }
})

export default router

import { prisma } from '../lib/prisma'
import { CreateSearchInput, Search, UpdateSearchInput } from '../types/search'

export async function getAllSearches(): Promise<Search[]> {
  return prisma.savedSearch.findMany({
    orderBy: { createdAt: 'desc' },
  })
}

export async function getSearchById(id: string): Promise<Search | null> {
  return prisma.savedSearch.findUnique({
    where: { id },
  })
}

const ALLOWED_RESULTS_PER_SEARCH = [5, 10, 20, 50]

export async function createSearch(input: CreateSearchInput): Promise<Search> {
  const resultsPerSearch = input.resultsPerSearch ?? 10

  if (!ALLOWED_RESULTS_PER_SEARCH.includes(resultsPerSearch)) {
    throw new Error('Invalid resultsPerSearch')
  }

  if (
    input.maxPrice !== undefined &&
    input.maxPrice !== null &&
    (typeof input.maxPrice !== 'number' || input.maxPrice <= 0)
  ) {
    throw new Error('Invalid maxPrice')
  }

  return prisma.savedSearch.create({
    data: {
      name: input.name,
      query: input.query,
      maxPrice: input.maxPrice ?? null,
      location: input.location,
      radius: input.radius,
      resultsPerSearch,
    },
  })
}

export async function updateSearch(
  id: string,
  input: UpdateSearchInput,
): Promise<Search | null> {
  const existing = await getSearchById(id)
  if (!existing) return null

  if (
    input.resultsPerSearch !== undefined &&
    !ALLOWED_RESULTS_PER_SEARCH.includes(input.resultsPerSearch)
  ) {
    throw new Error('Invalid resultsPerSearch')
  }

  if (
    input.maxPrice !== undefined &&
    input.maxPrice !== null &&
    (typeof input.maxPrice !== 'number' || input.maxPrice <= 0)
  ) {
    throw new Error('Invalid maxPrice')
  }

  return prisma.savedSearch.update({
    where: { id },
    data: {
      ...(input.name !== undefined && { name: input.name.trim() }),
      ...(input.query !== undefined && { query: input.query.trim() }),
      ...(input.location !== undefined && { location: input.location.trim() }),
      ...(input.radius !== undefined && { radius: input.radius }),
      ...(input.maxPrice !== undefined && { maxPrice: input.maxPrice }),
      ...(input.resultsPerSearch !== undefined && {
        resultsPerSearch: input.resultsPerSearch,
      }),
    },
  })
}

export async function updateSearchAfterRun(
  id: string,
  stats: {
    newListings: number
    totalScraped: number
    skippedDuplicates: number
    newListingIds: string[]
  },
): Promise<void> {
  await prisma.savedSearch.update({
    where: { id },
    data: {
      lastCheckedAt: new Date(),
      lastNewListings: stats.newListings,
      lastTotalScraped: stats.totalScraped,
      lastSkippedDuplicates: stats.skippedDuplicates,
      lastRunNewListingIds: stats.newListingIds,
    },
  })
}

export async function deleteSearch(id: string): Promise<boolean> {
  const result = await prisma.savedSearch.deleteMany({
    where: { id },
  })

  return result.count > 0
}

import { beforeEach, describe, expect, it, vi } from 'vitest'

const mockPrisma = vi.hoisted(() => ({
  savedSearch: {
    create: vi.fn(),
    update: vi.fn(),
    findUnique: vi.fn(),
  },
}))

vi.mock('../../src/lib/prisma', () => ({
  prisma: mockPrisma,
}))

import { createSearch, updateSearch } from '../../src/store/searches'
import type { CreateSearchInput, UpdateSearchInput } from '../../src/types/search'

const baseCreateInput: CreateSearchInput = {
  name: 'Test search',
  query: 'bike',
  location: 'Philadelphia, PA',
  radius: 10,
}

const existingSearch = {
  id: 'search-1',
  name: 'Test search',
  query: 'bike',
  maxPrice: null,
  location: 'Philadelphia, PA',
  radius: 10,
  resultsPerSearch: 10,
  isActive: true,
  lastCheckedAt: null,
  lastNewListings: 0,
  lastTotalScraped: 0,
  lastSkippedDuplicates: 0,
  lastRunNewListingIds: [],
  createdAt: new Date(),
}

beforeEach(() => {
  vi.clearAllMocks()
})

describe('createSearch maxPrice validation', () => {
  it('throws for a negative maxPrice', async () => {
    await expect(
      createSearch({ ...baseCreateInput, maxPrice: -1 }),
    ).rejects.toThrow('Invalid maxPrice')

    expect(mockPrisma.savedSearch.create).not.toHaveBeenCalled()
  })

  it('throws for a maxPrice of 0', async () => {
    await expect(
      createSearch({ ...baseCreateInput, maxPrice: 0 }),
    ).rejects.toThrow('Invalid maxPrice')

    expect(mockPrisma.savedSearch.create).not.toHaveBeenCalled()
  })

  it('succeeds for a positive maxPrice and passes it through to prisma', async () => {
    mockPrisma.savedSearch.create.mockResolvedValueOnce({
      ...existingSearch,
      maxPrice: 100,
    })

    await createSearch({ ...baseCreateInput, maxPrice: 100 })

    expect(mockPrisma.savedSearch.create).toHaveBeenCalledWith({
      data: expect.objectContaining({ maxPrice: 100 }),
    })
  })

  it('succeeds when maxPrice is null', async () => {
    mockPrisma.savedSearch.create.mockResolvedValueOnce(existingSearch)

    await createSearch({ ...baseCreateInput, maxPrice: null })

    expect(mockPrisma.savedSearch.create).toHaveBeenCalledWith({
      data: expect.objectContaining({ maxPrice: null }),
    })
  })

  it('succeeds when maxPrice is omitted', async () => {
    mockPrisma.savedSearch.create.mockResolvedValueOnce(existingSearch)

    await createSearch({ ...baseCreateInput })

    expect(mockPrisma.savedSearch.create).toHaveBeenCalledWith({
      data: expect.objectContaining({ maxPrice: null }),
    })
  })

  it('throws for an invalid resultsPerSearch', async () => {
    await expect(
      createSearch({ ...baseCreateInput, resultsPerSearch: 7 }),
    ).rejects.toThrow('Invalid resultsPerSearch')

    expect(mockPrisma.savedSearch.create).not.toHaveBeenCalled()
  })
})

describe('updateSearch maxPrice validation', () => {
  beforeEach(() => {
    mockPrisma.savedSearch.findUnique.mockResolvedValue(existingSearch)
  })

  it('throws for a negative maxPrice', async () => {
    await expect(
      updateSearch('search-1', { maxPrice: -1 } as UpdateSearchInput),
    ).rejects.toThrow('Invalid maxPrice')

    expect(mockPrisma.savedSearch.update).not.toHaveBeenCalled()
  })

  it('throws for a maxPrice of 0', async () => {
    await expect(
      updateSearch('search-1', { maxPrice: 0 } as UpdateSearchInput),
    ).rejects.toThrow('Invalid maxPrice')

    expect(mockPrisma.savedSearch.update).not.toHaveBeenCalled()
  })

  it('succeeds for a positive maxPrice and passes it through to prisma', async () => {
    mockPrisma.savedSearch.update.mockResolvedValueOnce({
      ...existingSearch,
      maxPrice: 250,
    })

    await updateSearch('search-1', { maxPrice: 250 })

    expect(mockPrisma.savedSearch.update).toHaveBeenCalledWith({
      where: { id: 'search-1' },
      data: { maxPrice: 250 },
    })
  })

  it('succeeds when maxPrice is null', async () => {
    mockPrisma.savedSearch.update.mockResolvedValueOnce(existingSearch)

    await updateSearch('search-1', { maxPrice: null })

    expect(mockPrisma.savedSearch.update).toHaveBeenCalledWith({
      where: { id: 'search-1' },
      data: { maxPrice: null },
    })
  })

  it('succeeds when maxPrice is omitted, leaving it untouched', async () => {
    mockPrisma.savedSearch.update.mockResolvedValueOnce(existingSearch)

    await updateSearch('search-1', { name: 'Renamed search' })

    expect(mockPrisma.savedSearch.update).toHaveBeenCalledWith({
      where: { id: 'search-1' },
      data: { name: 'Renamed search' },
    })

    const callArgs = mockPrisma.savedSearch.update.mock.calls[0][0]
    expect(callArgs.data).not.toHaveProperty('maxPrice')
  })

  it('throws for an invalid resultsPerSearch', async () => {
    await expect(
      updateSearch('search-1', { resultsPerSearch: 7 } as UpdateSearchInput),
    ).rejects.toThrow('Invalid resultsPerSearch')

    expect(mockPrisma.savedSearch.update).not.toHaveBeenCalled()
  })
})

